#!/bin/bash
# Check the schematic and the board (ERC, DRC with schematic parity) and
# write the fabrication outputs to fab/ (Gerbers + drill zip, BOM,
# placement, schematic PDF, board images) from the files as they are.
#
# The KiCad files are generated by tools/gen_sch.py / gen_pcb.py
# (`--regen` rebuilds them first). Once they are edited in KiCad, the
# KiCad files become the master and --regen would discard those edits.
set -euo pipefail
cd "$(dirname "$0")/.."
N=Pmod_10BASE_T1S
export TMPDIR=${TMPDIR:-/tmp}
CPNR=${CPNR:-$HOME/repos/circuitpnr/target/release/cpnr}
if [ "${1:-}" = "--regen" ]; then
    python3 tools/gen_sch.py
    python3 tools/gen_pcb.py 2>&1 | grep -v 'assert' || true
    # copper: routed by circuitpnr (the B.Cu GND pour is drawn by gen_pcb.py)
    "$CPNR" route $N.kicad_pcb -o $TMPDIR/$N.routed.kicad_pcb \
        --params '{"time_limit":300,"feedback_rounds":3,"via_cost":3,"layers":["F.Cu","B.Cu"]}' >/dev/null
    cp $TMPDIR/$N.routed.kicad_pcb $N.kicad_pcb
    # reference designators: placed by circuitpnr (cpnr labels). pad_clip 0 / edge_clearance 0.5 keep
    # KiCad DRC clean (no silk on pads, J1 clear of the edge); trim_leaders.py lifts leader ends off their
    # own part's silk. The result varies from run to run, so repeat until both cpnr label-check and the
    # silk rules of KiCad DRC are clean (both are checked again below)
    for i in 1 2 3 4 5 6 7 8; do
        "$CPNR" labels --params '{"all":true,"pad_clip":0,"edge_clearance":0.5}' -o $TMPDIR/$N.labels.kicad_pcb $N.kicad_pcb >/dev/null
        cp $TMPDIR/$N.labels.kicad_pcb $N.kicad_pcb
        python3 tools/trim_leaders.py $N.kicad_pcb 2>&1 | grep -v 'assert\|trim_leaders' || true
        kicad-cli pcb drc --severity-all -o $TMPDIR/$N.silk.rpt $N.kicad_pcb >/dev/null
        if ! "$CPNR" label-check $N.kicad_pcb | grep -q '"kind"' && ! grep -q '^\[silk' $TMPDIR/$N.silk.rpt; then
            echo "labels: pass $i clean"; break
        fi
    done
fi
mkdir -p fab/gerber
"$CPNR" label-check $N.kicad_pcb > fab/label_check.json
if grep -q '"kind"' fab/label_check.json; then echo "== fab/label_check.json:"; cat fab/label_check.json; exit 1; fi
# library-table warnings are environment dependent (headless kicad-cli without global tables)
kicad-cli sch erc --severity-all -o fab/erc.rpt $N.kicad_sch >/dev/null
kicad-cli pcb drc --schematic-parity --refill-zones --severity-all -o fab/drc.rpt $N.kicad_pcb >/dev/null
for f in fab/erc.rpt fab/drc.rpt; do
    if grep '^\[' "$f" | grep -qv 'lib_symbol_issues\|footprint_link_issues\|lib_footprint_issues'; then
        echo "== $f:"; grep '^\[' "$f" | grep -v 'lib_symbol_issues\|footprint_link_issues\|lib_footprint_issues' | sort | uniq -c
        exit 1
    fi
done
grep -h 'unconnected\|parity' fab/drc.rpt || true
rm -f fab/gerber/*
# Gerbers, drill and placement all relative to the drill/place origin (board lower-left corner), so
# that JLCPCB lines the CPL up with the board
kicad-cli pcb export gerbers --layers F.Cu,B.Cu,F.Paste,F.Silkscreen,B.Silkscreen,F.Mask,B.Mask,Edge.Cuts \
    --subtract-soldermask --no-x2 --use-drill-file-origin -o fab/gerber/ $N.kicad_pcb >/dev/null
kicad-cli pcb export drill --format excellon --excellon-separate-th --drill-origin plot -o fab/gerber/ $N.kicad_pcb >/dev/null
(cd fab/gerber && rm -f ../${N}_gerber.zip && zip -q ../${N}_gerber.zip *)
kicad-cli pcb export pos --side front --format csv --units mm --use-drill-file-origin -o fab/${N}_pos.csv $N.kicad_pcb >/dev/null
kicad-cli sch export bom --fields 'Reference,Value,Footprint,${QUANTITY},LCSC,MPN,Description' \
    --group-by Value,Footprint --exclude-dnp -o fab/${N}_bom.csv $N.kicad_sch >/dev/null
kicad-cli sch export bom --fields 'Reference,Value,Footprint,${QUANTITY},LCSC,MPN' \
    --group-by Value,Footprint,LCSC --exclude-dnp -o fab/${N}_bom_full.csv $N.kicad_sch >/dev/null
python3 tools/jlc_files.py $N fab
kicad-cli sch export pdf -o fab/${N}_schematic.pdf $N.kicad_sch >/dev/null
kicad-cli pcb render --side top --width 1600 --height 1200 --perspective --rotate "-35,0,20" --zoom 1.1 \
    -o fab/${N}_3d.png $N.kicad_pcb >/dev/null
kicad-cli pcb render --side top --width 1200 --height 1200 -o fab/${N}_top.png $N.kicad_pcb >/dev/null
kicad-cli pcb render --side bottom --width 1200 --height 1200 -o fab/${N}_bottom.png $N.kicad_pcb >/dev/null
ls fab
